from lib import *
S = SS('f184')
R = J('f184'); T = R['types']; SC = R['secret']; O = R['order']['steps']; E = R['envvar']
steps = [
    step(f"app.config.from_prefixed_env('APP') 把 APP_ 开头的环境变量读进 config,每个值先当 JSON 解析,解析不了就保留字符串:'42' → int 42;'true' → bool True;'false' → bool False;'[1,2]' → list;'1.5' → float;'null' → None;'abc' → str;大写的 'True' 不是合法 JSON → 保留字符串 'True'(用 'True' 来写布尔值会得到字符串,条件判断恒为真);APP_I__J=x 里的双下划线表示嵌套 → config['I'] = {T['I']}。对比自己用 os.environ.get 拿到的永远是字符串,bool('0')、bool('false') 都是 True。写法要选一种并统一。", t=tl(S(1)), done=lidx(S(1), "'42'", "'true'", "'false'", 'APP_I__J'), mark=lidx(S(1), "'True'", '对比'), kv=KV([["'false'", 'bool False'], ["'True'", "字符串 'True'"], ['os.environ.get', '永远是字符串']], ["'True'"])),
    step(f"同一个机制对 SECRET_KEY 有坑:APP_SECRET_KEY='12345' 被解析成 {SC['12345'][0]},访问用到 session 的视图 → HTTP {SC['12345'][1]}(签名需要 bytes 或 str);'1e3' 被解析成 {SC['1e3'][0]} → {SC['1e3'][1]};'true' 被解析成 {SC['true'][0]} → {SC['true'][1]};'abcdef' 和 's3cr3t-key' 保持 str → {SC['abcdef'][1]}。一个纯数字的密钥或密码在配置里变成了数字,应用在第一次用到它时才 500(而不是启动时报错)。对密钥、密码、令牌这类值,不要靠自动转换:自己 os.environ['X'] 直接读,或者用 str() 再赋给 config。", t=tl(S(2)), done=lidx(S(2), 'abcdef', 's3cr3t'), mark=lidx(S(2), '12345', '1e3', "'true'"), kv=KV([['12345', f"{SC['12345'][0]} → HTTP 500"], ['abcdef', 'str → HTTP 200']], ['12345'])),
    step(f"加载顺序是后者覆盖前者:from_mapping 的默认值 LEVEL='default' → from_pyfile(base.py) 变成 {O[1][1]['LEVEL']!r} → from_prefixed_env 变成 {O[2][1]['LEVEL']!r};没有被后面覆盖的键保持上一步的值(NAME 保持 {O[2][1]['NAME']!r},ONLY_DEFAULT 保持 {O[2][1]['ONLY_DEFAULT']})。常见的顺序是默认值 → 配置文件 → 环境变量,环境变量最后加载,所以最优先。", t=tl(S(3)), done=lidx(S(3), 'from_prefixed_env'), mark=[], kv=KV([['顺序', '默认 → 文件 → 环境变量'], ['最后加载', '优先']], ['最后加载'])),
    step(f"from_envvar(NAME) 读的是一个环境变量里写的配置文件路径:变量没设 → {E['unset'][0]}(消息里说明变量没设);silent=True → 返回 {E['silent']},什么都不做也不报错(配置缺失会被悄悄忽略);指向 prod.cfg → 返回 {E['loaded'][0]},MODE={E['loaded'][1]!r};指向一个不存在的文件 → {E['missingfile'][0]}。生产启动时缺配置宁可失败也不要 silent。另一点:.env 文件——python-dotenv 装了以后,flask 命令(flask --app ... show)会读到 DOT_VAR={R['dot_flask'].split(': ')[1]},而 gunicorn 里视图读到的是 {R['dot_gunicorn']}:gunicorn 不会读 .env,开发和生产的环境变量来源不同,不要依赖它。", t=tl(S(4)), done=lidx(S(4), '指向 prod.cfg'), mark=lidx(S(4), '变量没设', 'silent', '不存在的文件'), kv=KV([['from_envvar 变量没设', 'RuntimeError'], ['silent=True', '悄悄返回 False']], ['silent=True'])),
]
A = mkartf('f184', 184, 'Flask,环境变量,配置,from_prefixed_env,python-dotenv,真实验证,动画演示',
    f'真实运行验证 Flask 的环境变量注入:from_prefixed_env 把值按 JSON 解析(\'True\' 保留为字符串)、纯数字的 SECRET_KEY 被解析成 int 导致 session 500、后加载的覆盖先加载的、from_envvar 的 RuntimeError 与 silent、.env 只被 flask 命令读取而 gunicorn 不读。',
    '配置从环境变量来,是容器和 12-factor 部署的常规做法。Flask 提供了 from_prefixed_env 与 from_envvar,但转换规则里有个坑。这篇用真实的进程逐项验证类型转换、密钥的陷阱、加载顺序以及 .env 的行为(生产环境关闭 DEBUG 见第 186 篇,密钥轮换见第 187 篇)。',
    [("int", "APP_SECRET_KEY='12345' 被解析成的类型,session 随即 500"), ('后者覆盖前者', '默认 → 配置文件 → 环境变量'), ('.env', 'flask 命令会读,gunicorn 不读')],
    [('类型转换', '<p>上一篇:<a href="flask-error-monitoring.html">错误监控</a>;下一篇:<a href="flask-multiprocess-log-duplication.html">多进程日志重复问题</a>。</p>'), ('SECRET_KEY 的坑', None), ('加载顺序', None), ('from_envvar 与 .env', None)],
    steps, [ENV_F + '。python-dotenv 1.2.4、gunicorn', '没有验证:Docker/Kubernetes 注入环境变量的方式(Secret、ConfigMap)、systemd EnvironmentFile、其它配置库(pydantic-settings、dynaconf)、环境变量的进程内可见性与泄漏途径、配置热更新'], 'Flask 环境变量注入')
